	/* @Override */
	protected void removeTargetSoftwareBreakpoint(TraceRmiTarget target)
    {
		Trace trace = target.getTrace();
		long snap = target.getSnap();
		Lifespan nowOn = Lifespan.nowOn(snap);
		List<TraceBreakpointLocation> locsToDel = trace.getBreakpointManager()
				.getAllBreakpointLocations()
				.stream()
				.filter(loc => loc.getKinds(snap).equals(CommonSet.SWX.kinds()))
				.toList();
		List<TraceBreakpointSpec> specsToDel =
			locsToDel.stream().map(bp => bp.getSpecification()).distinct().toList();
		using (Transaction tx = trace.openTransaction("Delete software breakpoints"))
{
			foreach (TraceBreakpointLocation loc in locsToDel) {
				loc.getObject().remove(nowOn);
			}
			foreach (TraceBreakpointSpec spec in specsToDel) {
				spec.getObject().remove(nowOn);
			}
		}
		waitForDomainObject(trace);
	}

